package com.nexamart.backend.repository;import com.nexamart.backend.domain.Notification;import com.nexamart.backend.domain.NotificationType;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface NotificationRepository extends JpaRepository<Notification,Long>{void deleteByUserId(Long userId);Page<Notification> findByUserId(Long userId,Pageable p);long countByUserIdAndReadFlagFalse(Long userId);boolean existsByUserIdAndOrderIdAndType(Long userId,Long orderId,NotificationType type);java.util.List<Notification> findByUserIdAndReadFlagFalse(Long userId);@Query("select n from Notification n where n.user.id=:userId and (:unreadOnly=false or n.readFlag=false) order by n.createdAt desc")Page<Notification> search(@Param("userId")Long userId,@Param("unreadOnly")boolean unreadOnly,Pageable p);}
